    try:
        img = pil_loader(path)
        return img
    except (OSError, Image.UnidentifiedImageError, Exception) as e:
        # Skip corrupted images
        raise FileNotFoundError(f"Cannot load image {path}: {e}")

# Create a dataset with safe loading
class SafeImageFolder(ImageFolder):
    def __init__(self, root, transform=None):
        super().__init__(root, transform=transform, loader=custom_loader)

    def __getitem__(self, index):
        # Skip items that fail to load
        while True:
            try:
                return super().__getitem__(index)
            except (FileNotFoundError, Image.UnidentifiedImageError, OSError, Exception):
                # Move to next index if current fails
                # Return a valid random image as fallback
                # Try a different index
                index = (index + 1) % len(self)

