        super(SafeImageFolder, self).__init__(root, transform=transform)
        # Filter out corrupted images
        self.valid_indices = []
        for i, (path, _) in enumerate(self.samples):
            try:
                with open(path, 'rb') as f:
                    img = Image.open(f)
                    img.verify()
                    img = Image.open(f).convert('RGB')
                    self.valid_indices.append(i)
            except (OSError, Image.UnidentifiedImageError, Exception):
                # Skip corrupted images
                pass
        self.samples = [self.samples[i] for i in self.valid_indices]
        self.imgs = self.samples

    def __getitem__(self, index):
        path, target = self.samples[index]
        try:
            sample = self.loader(path)
            if self.transform is not None:
                sample = self.transform(sample)
            if self.target_transform is not None:
                target = self.target_transform(target)
            return sample, target
        except Exception:
            # If loading fails, pick a random different sample
            new_index = (index + 1) % len(self)
            return self.__getitem__(new_index)

    def __len__(self):
        return len(self.samples)

