print("Directory structure:")
root = "data_small/celeba_hq_256"
if os.path.exists(root):
    for item in os.listdir(root):
        item_path = os.path.join(root, item)
        if os.path.isdir(item_path):
            count_files = len([f for f in os.listdir(item_path) if os.path.isfile(os.path.join(item_path, f))])
            print(f"  {item}/ (directory, {count_files} files)")
            # Show first few items in this subdirectory
            sub_items = os.listdir(item_path)[:5]
            for sub_item in sub_items:
                sub_path = os.path.join(item_path, sub_item)
                if os.path.isfile(sub_path):
                    print(f"    - {sub_item}")
        else:
            print(f"  {item} (file)")
else:
    print(f"Root directory {root} does not exist")

# Now let's create our dataset - we'll use ImageFolder directly but handle errors gracefully
class SafeImageFolder(ImageFolder):
    def __init__(self, root, transform=None):
        super(SafeImageFolder, self).__init__(root, transform=transform)

        print("\nScanning dataset for corrupted images...")
        total_count = len(self.samples)
        valid_samples = []

        for path, target in self.samples:
            try:
                # Check file size - skip tiny files (< 500 bytes) which are likely corrupted
                file_size = os.path.getsize(path)
                if file_size < 500:
                    continue

                # Try using Image.open directly
                from PIL import Image
                with Image.open(path) as img:
                    img.load()  # Force loading to verify the image

                valid_samples.append((path, target))
            except Exception as e:
                # Skip corrupted images
                pass

        self.samples = valid_samples
        self.imgs = self.samples
        print(f"Found {len(self.samples)} valid images (filtered out {total_count - len(self.samples)} corrupted images)")

        if len(self.samples) == 0:
            raise ValueError("No valid images found in the dataset!")

dataset = SafeImageFolder(root="data_small/celeba_hq_256",
                         transform=transformer)"}

